  Defined.

  Definition All3_fold_ofε P P' Γ Γ' Γ'' :
    [(H : All3_fold P Γ Γ' Γ'')] ->
    [(X : All3_foldε P (fun Γ Γ' Γ'' d d' d'' _ => P' Γ Γ' Γ'' d d' d'') Γ Γ' Γ'' H)] ->
    All3_fold P' Γ Γ' Γ''.
  Proof.
    intros H X.
    induction X; constructor; eauto.
