  Definition All3_fold_fmap_ofε P Q Q' Γ Γ' Γ'' :
    [(p : All3_fold P Γ Γ' Γ'')] ->
    [(H : All3_foldε P Q Γ Γ' Γ'' p)] ->
    [(X Γ Γ' Γ'' d d' d'' wfΓ Xd : All3_foldε P Q Γ Γ' Γ'' wfΓ -> All3_fold Q' Γ Γ' Γ'' -> Q Γ Γ' Γ'' d d' d'' Xd -> Q' Γ Γ' Γ'' d d' d'')] ->
    All3_fold Q' Γ Γ' Γ''.
  Proof.
    intros p H X.
    induction H; constructor; eauto.
