  [(onP' T H : P' T H -> P'' (lift #|Δ| #|Ξ| T))] ->
  [(H : checking Σ P (Γ ,,, Ξ) T)] ->
  [(X : checkingε Σ P P' (Γ ,,, Ξ) T H)] ->
  checking Σ P'' (Γ ,,, Δ ,,, lift_context #|Δ| 0 Ξ) (lift #|Δ| #|Ξ| T).
