Lemma wf_judgment_CC_pre TC tc Σ P (P' : forall Γ t T, P Γ t T -> Type) Γ Δ j :
  [(onP' t T H : P' Γ t T H -> Σ ;;; Δ ⊢ t : T)] ->
  [(H : wf_judgment Σ Γ j with P)] ->
