Lemma wf_judgment_CCR_pre TC tc Σ P (P' : forall Γ t T, P Γ t T -> Type) Γ Δ Δ' j :
  [(onP' t T H : P' (Γ ,,, Δ) t T H -> Σ ;;; Γ ,,, Δ' ⊢ t : T)] ->
  [(H : wf_judgment Σ (Γ ,,, Δ) j with P)] ->
  [(X : wf_judgment Σ (Γ ,,, Δ) j on H with P')] ->
