  Lemma kind_no_cast2_toε R R' Rs P Γ Γ' t t' T T' u u' :
    [(p : kind_no_cast2 Σ R Rs P t t' Γ Γ' T T' u u')] ->
    [(X t t' T T' : [(H : R Γ Γ' t t' T T')] -> R' Γ Γ' t t' T T' H)] ->
    kind_no_cast2ε Σ R R' Rs P t t' Γ Γ' T T' u u' p.
  Proof.
