    * now apply do_lift with (t := tProd _ _ B₀).
    * now apply do_lift with (t := tProd _ _ B₀'). *)
  - now eapply wf_judgment2_mixed_lift_pre with (j := j_vass _ _) (j' := j_vass _ _).
  - eapply onPT' with (Ξ := Ξ ,, _) (Ξ' := Ξ' ,, _) in IXB₀. 2: cbn; lia.
