Definition eq3 {A B} P Γ Γ' (t t' : A) (T T' : B) := P Γ t T × Γ = Γ' × t = t' × T = T'.

Definition eq_output : OneOutput := {|
  Ri := eq3 (fun Γ t T => Σ ;;; Γ ⊢ t ▹ T);
  Rc := eq3 (fun Γ t T => Σ ;;; Γ ⊢ t : T);
  RT := eq3 (fun Γ T s => Σ ;;; Γ ⊢ T : tSort s);
  Rα := eq; Rs := eq
|}.

