    1: eapply do_wf_subst3 with (Δ := [vass na A]) (Δ' := [vass na' A']) (Δ'' := [vass na'' A'']) (Ξ := []) (Ξ' := []) (Ξ'' := []) (T := tSort _) (T' := tSort _) (T'' := tSort _); trea.
