  Notation "Σ ;;; Γ ⊢ t ≡>h t' ▹ T " := (Σ ;;; Γ ⊢ t ~hh t' ▹ T with pred0 Σ _ Γ, _).
  Notation "Σ ;;; Γ ⊢ t ≡>h t' ▹ T 'with' R" := (Σ ;;; Γ ⊢ t ~hh t' ▹ T with pred0 Σ R Γ, R) (only parsing).
