Lemma RightTyping_Lambda {Pre : TCProd_contra Σ} Γ na na' A A' t B :
  wf_local Σ Γ ->
  [(e : eq_binder_annot na na')] ->
  [(Xj : wf_judgment Σ Γ (j_vass na A))] ->
  [(XTA : Σ ;;; Γ ⊢ A ≤T A')] ->
  [(XTA' : Σ ;;; Γ ⊢ A' ≤T A)] ->
  [(Xt : Σ ;;; Γ ,, vass na' A' ⊢ t : B)] ->
