Inductive pred1_trans {TC} Σ Γ t t' t'' T : Type :=
  | pred1_trans_pred0 :
      [(X : Σ ;;; Γ ⊢ t ≡>0 t' ≡>0 t'' ▹ T with fun Γ t t' t'' T => Σ ;;; Γ ⊢ t ≡> t' ≡> t'' : T)] ->
