Inductive hred1 {TC RedW} Σ Γ t u T :=
  | hred1_red0 :
      [(X : Σ ;;; Γ ⊢ t ~>0 u ▹ T)] ->
      Σ ;;; Γ ⊢ t ~>h u ▹ T

  | hred1_clos1 :
      [(X : Σ ;;; Γ ⊢ t ~h1 u ▹ T with hred1 Σ Γ)] ->
      Σ ;;; Γ ⊢ t ~>h u ▹ T
where "Σ ;;; Γ ⊢ t ~>h t' ▹ T" := (hred1 Σ Γ t t' T).
