  | hred_step t u v T T' :
      [(Xt : Σ ;;; Γ ⊢ t ~>h u ▹ T)] ->
      [(Xu : Σ ;;; Γ ⊢ u ~>h* v ▹ T')] ->
      Σ ;;; Γ ⊢ t ~>h* v ▹ T
where " Σ ;;; Γ ⊢ t ~>h* t' ▹ T " := (hred Σ Γ t t' T).

Derive Signature for hred.

Definition hred_rect TC RedW Σ Γ P :
  [(XRefl t T :
      [(Xt : Σ ;;; Γ ⊢ t ▹ T)] ->
      P t t T ⌈hred_refl⌋)] ->
  [(XStep t t' t'' T T' :
      [(Xt : Σ ;;; Γ ⊢ t ~>h t' ▹ T)] ->
      [(Xu : Σ ;;; Γ ⊢ t' ~>h* t'' ▹ T')] ->
      P t' t'' T' Xu ->
      P t t'' T ⌈hred_step⌋)] ->
  forall t u T, [(X : Σ ;;; Γ ⊢ t ~>h* u ▹ T)] -> P t u T X.
Proof.
  intros.
  revert t u T X.
  fix Xrec 4.
  intros t u T X; destruct X.
  - apply XRefl; eauto with fmap.
  - eapply XStep; eauto.
Defined.




