Lemma LeftInfer_pred0 P P' Γ t u T :
  [(onP' Γ t u T H : P' Γ t u T H -> Σ ;;; Γ ⊢ t ▹ T)] ->
  [(H : Σ ;;; Γ ⊢ t ≡>0 u ▹ T with P)] ->
