  where "Σ ;;; Γ ⊢ t ~>0 t' ▹ T" := (red0 Γ t t' T) (only parsing).
  Derive Signature for red0.

  Inductive eta_red0 Γ t : forall (t' T : term), Type :=
    | eta_nored T :
        [(X : Σ ;;; Γ ⊢ t ▹ T)] ->
        Σ ;;; Γ ⊢ t ~>η0 t ▹ T

    | eta_red0_prod na A B :
        [(X : Σ ;;; Γ ⊢ t ▹Π (na : A), B)] ->
