    | elim_clos_prod na na' A A' B B' T s T' s' :
        [(Xα : Rα na na')] ->
        [(XA : Σ ;;; Γ ⊢ A ~R A' ▹ T)] ->
        [(XT : Σ ;;; Γ ⊢ T ~>□ s)] ->
        [(Xs : isSortRel s na.(binder_relevance))] ->
        [(XB : Σ ;;; Γ ,, vass na A ⊢ B ~R B' ▹ T')] ->
