    | elim_closε_prod na na' A A' B B' T s T' s' :
        [(Xα : Rα na na')] ->
        [(XA : Σ ;;; Γ ⊢ A ~R A' ▹ T)] ->
        [(IXA : Σ ;;; Γ ⊢ A ~R' A' ▹ T on XA)] ->
        [(XT : Σ ;;; Γ ⊢ T ~>□ s)] ->
        [(Xs : isSortRel s na.(binder_relevance))] ->
