  Lemma infer_red2_toε R R' Γ Γ' T T' :
    [(p : Σ ;;; Γ | Γ' ⊢ _ ~R _ ▹↘ T | T' with0 R)] ->
    [(X T T' : [(H : R T T')] -> R' T T' H)] ->
    Σ ;;; Γ | Γ' ⊢ _ ~R' _ ▹↘ T | T' on p with0 R'.
  Proof.
