  Definition equality_Conv_rect cf TC RedW Σ P :
    [(XSProp Γ Γ' t t' T T' T₀ :
        [(Xt : Σ ;;; Γ ⊢ t ▹ T)] ->
        [(Xt' : Σ ;;; Γ' ⊢ t' ▹ T')] ->
        [(XT : Σ ;;; Γ ⊢ T ≤T T₀)] ->
