  Fixpoint ρ t :=
    match t with
    | tApp (tLambda na A t) u => (ρ t) {0 := ρ u}
    | tApp t u => tApp (ρ t) (ρ u)
    | tLambda na A t => tLambda na (ρ A) (ρ t)
    | tProd na A B => tProd na (ρ A) (ρ B)
    | tSort s => tSort s
    | t => t
    end.


