  | hred1_cumul t u T U :
      Σ ;;; Γ ⊢ t ~>h u : T ->
      Σ ;;; Γ ⊢ T ≤T U ->
      Σ ;;; Γ ⊢ t ~>h u : U

  | hred1_clos1 t u T :
      Σ ;;; Γ ⊢ t ~h1 u : T with hred1 Σ ->
      Σ ;;; Γ ⊢ t ~>h u : T
