  [(Xred0 Γ t u T : Σ ;;; Γ ⊢ t ~>0 u : T -> P Γ t u T)] ->
  [(XCumul Γ t u A B :
      Σ ;;; Γ ⊢ t ~>h u : A ->
      P Γ t u A ->
      Σ ;;; Γ ⊢ A ≤T B with TC ->
      P Γ t u B )] ->
  [(XClosure Γ t u T :
      [(Htu : Σ ;;; Γ ⊢ t ~h1 u : T with hred1 Σ)] ->
      [(Xtu : Σ ;;; Γ ⊢ t ~h1 u : T on Htu with P)] ->
      P Γ t u T )] ->

  forall Γ t u T, [(X : Σ ;;; Γ ⊢ t ~>h u : T)] -> P Γ t u T.
