  intros.
  revert Γ t u T X.
  fix Xrec 5.
  intros Γ t_ u_ T_ []; try clear t_; try clear u_; try clear T_.
  - apply Xred0; eauto.
  - eapply XCumul; eauto.
  - unshelve eapply XClosure; eauto with fmap.
