  [(XCumul Γ pb t u T U :
      Σ ;;; Γ ⊢ t <==[pb] u : T ->
      P Γ pb t u T ->
      Σ ;;; Γ ⊢ T ≤T U ->
      P Γ pb t u U )] ->
  [(XClosure Γ pb t u T :
      [(H : Σ ;;; Γ ⊢ t ~ u : T with (fun Γ => conv Σ Γ Conv), eq_binder_annot, eq_sort Σ)] ->
      [(X : Σ ;;; Γ ⊢ t ~ u : T on H with (fun Γ => P Γ Conv))] ->
