Proof.
  intros.
  induction H.
  all: try now econstructor; eauto with fmap.
Defined.

Lemma eta_right_spine_toε {cf} Σ R' Ξ Δ t t' :
  [(p : Σ ;;; Ξ ⊢ t · Δ =η t')] ->
  [(X Ξ t t' : [(H : eta_spine Σ Ξ t t')] -> R' Ξ t t' H)] ->
