Defined.

Lemma eta_right_spineε_fmap {cf} Σ R R' Ξ Δ t t' :
  [(p : Σ ;;; Ξ ⊢ t · Δ =η t')] ->
  [(H : Σ ;;; Ξ ⊢ t · Δ =η t' on p with R)] ->
