  [(Htu : Σ ;;; Ξ ⊢ t =η u · Δ')] ->
  [(Huv : Σ ;;; Ξ ⊢ u =η v · Δ)] ->
  [(IH x : eta_spine_pack_size Σ x < eta_left_spine_size (@eta_spine_size cf Σ) Htu + eta_left_spine_size (@eta_spine_size cf Σ) Huv -> Goal Σ x)] ->
