Lemma case_right_right cf Σ Ξ Δ Δ' t u v :
  [(Htu : Σ ;;; Ξ ⊢ t · Δ =η u)] ->
  [(Huv : Σ ;;; Ξ ⊢ u · Δ' =η v)] ->
  [(IH x : eta_spine_pack_size Σ x < eta_right_spine_size (@eta_spine_size cf Σ) Htu + eta_right_spine_size (@eta_spine_size cf Σ) Huv -> Goal Σ x)] ->
