Lemma conv_conv' cf TC Σ (Pre : TypedReflexivity (pred1 Σ) Σ) Γ pb t u T :
  Σ ;;; Γ ⊢ t <==[pb] u : T ->
  Σ ;;; Γ ⊢ t <===[pb] u : T.
Proof.
  induction 1.
