        [(IXtu : Σ ;;; Γ ⊢ t ~ext u : A on Xtu with (fun Γ t u A => forall v w pb' B T, Σ ;;; Γ ⊢ v <==[pb'] w : B -> Σ ;;; Γ ⊢ A ≤* T -> Σ ;;; Γ ⊢ B ≤* T ->  Σ ;;; Γ ⊢ t <==[pb] u | v <==[pb'] w : A ≤ T ≥ B))] ->
